// ---------------------------------------------------------------------------
// input_1_datapath_core: auto-generated by datapath_gen.py -- do not edit by hand
//
// Protocol: hold `start` for a cycle with ce=1 while idle; inputs are latched,
// so they may change afterwards. Outputs are valid while `done` is high and
// stay valid until the next `start`.
// Latency: 11 cycles from the cycle `start` is sampled to `done`.
// ---------------------------------------------------------------------------
`timescale 1ns/1ps
module input_1_datapath_core #(
    parameter WIDTH = 4
)(
    input  wire             clk,
    input  wire             rst,
    input  wire             ce,      // 1 = run; 0 = freeze everything
    input  wire             start,
    input  wire [WIDTH-1:0] in_A,
    input  wire [WIDTH-1:0] in_C,
    input  wire [WIDTH-1:0] in_B,
    output wire [WIDTH-1:0] out_Q,
    output wire [WIDTH-1:0] out_Z,
    output wire [WIDTH-1:0] out_Y,
    output wire [WIDTH-1:0] out_X,
    output wire [WIDTH-1:0] dbg_add0_out,   // debug: raw unit output
    output wire [WIDTH-1:0] dbg_mul0_out,   // debug: raw unit output
    output wire [WIDTH-1:0] dbg_sub0_out,   // debug: raw unit output
    output wire [3:0]       dbg_state,
    output wire             busy,
    output wire             done
);

    localparam LAT_ADD = 3;
    localparam LAT_SUB = 3;
    localparam LAT_MUL = 3;

    // ------------------------------------------------------------ FSM
    localparam [3:0] S_IDLE = 4'd0;
    localparam [3:0] S_DONE = 4'd11;
    reg [3:0] state;
    always @(posedge clk) begin
        if (rst)                state <= S_IDLE;
        else if (ce) case (state)
            S_IDLE: if (start)  state <= 1;
            S_DONE:             state <= S_IDLE;
            default:            state <= state + 1'b1;   // control steps 1..10
        endcase
    end
    assign busy = (state != S_IDLE);
    assign done = (state == S_DONE);
    assign dbg_state = state;

    // ------------------------------------------------------------ control signals
    reg r0_we;
    reg r1_we;
    reg r2_we;
    reg r3_we;
    reg [0:0] add0_b_sel;
    reg [0:0] r0_sel;
    reg [0:0] r1_sel;
    reg [0:0] r2_sel;

    always @(*) begin
        r0_we = 1'b0;
        r1_we = 1'b0;
        r2_we = 1'b0;
        r3_we = 1'b0;
        add0_b_sel = 1'd0;
        r0_sel = 1'd0;
        r1_sel = 1'd0;
        r2_sel = 1'd0;
        case (state)
            S_IDLE: begin
                if (start) begin   // latch primary inputs
                    r0_we = 1'b1;  // r0 <= C
                    r0_sel = 1'd0;
                    r1_we = 1'b1;  // r1 <= A
                    r1_sel = 1'd0;
                    r2_we = 1'b1;  // r2 <= B
                    r2_sel = 1'd0;
                end
            end
            4'd1: begin
                // issue X2 = A + C on add0  (a <- r1, b <- r0)
                add0_b_sel = 1'd0;
            end
            4'd4: begin
                // issue Y = X2 + A on add0  (a <- r1, b <- add0_out)
                add0_b_sel = 1'd1;
                // issue Z = X2 - B on sub0  (a <- add0_out, b <- r2)
                r0_we = 1'b1;  // r0 <= X2
                r0_sel = 1'd1;
            end
            4'd7: begin
                // issue Q = B * Z on mul0  (a <- r2, b <- sub0_out)
                r1_we = 1'b1;  // r1 <= Y
                r1_sel = 1'd1;
                r2_we = 1'b1;  // r2 <= Z
                r2_sel = 1'd1;
            end
            4'd10: begin
                r3_we = 1'b1;  // r3 <= Q
            end
            default: ;
        endcase
    end

    // ------------------------------------------------------------ functional units
    wire [WIDTH-1:0] add0_a = r1;
    reg  [WIDTH-1:0] add0_b;
    always @(*) begin
        case (add0_b_sel)
            1'd0: add0_b = r0;
            1'd1: add0_b = add0_out;
            default: add0_b = {WIDTH{1'b0}};
        endcase
    end
    wire [WIDTH-1:0] add0_out;
    adder #(.WIDTH(WIDTH), .NUM_PIPE_CYCLES(LAT_ADD)) u_add0 (
        .clk(clk), .ce(ce), .a(add0_a), .b(add0_b), .out(add0_out));
    assign dbg_add0_out = add0_out;

    wire [WIDTH-1:0] mul0_a = r2;
    wire [WIDTH-1:0] mul0_b = sub0_out;
    wire [WIDTH-1:0] mul0_out;
    multiplier #(.WIDTH(WIDTH), .NUM_PIPE_CYCLES(LAT_MUL)) u_mul0 (
        .clk(clk), .ce(ce), .a(mul0_a), .b(mul0_b), .out(mul0_out));
    assign dbg_mul0_out = mul0_out;

    wire [WIDTH-1:0] sub0_a = add0_out;
    wire [WIDTH-1:0] sub0_b = r2;
    wire [WIDTH-1:0] sub0_out;
    subtractor #(.WIDTH(WIDTH), .NUM_PIPE_CYCLES(LAT_SUB)) u_sub0 (
        .clk(clk), .ce(ce), .a(sub0_a), .b(sub0_b), .out(sub0_out));
    assign dbg_sub0_out = sub0_out;

    // ------------------------------------------------------------ registers
    // r0 holds: C, X2
    reg  [WIDTH-1:0] r0_d;
    always @(*) begin
        case (r0_sel)
            1'd0: r0_d = in_C;
            1'd1: r0_d = add0_out;
            default: r0_d = {WIDTH{1'b0}};
        endcase
    end
    reg  [WIDTH-1:0] r0;
    always @(posedge clk) if (ce && r0_we) r0 <= r0_d;

    // r1 holds: A, Y
    reg  [WIDTH-1:0] r1_d;
    always @(*) begin
        case (r1_sel)
            1'd0: r1_d = in_A;
            1'd1: r1_d = add0_out;
            default: r1_d = {WIDTH{1'b0}};
        endcase
    end
    reg  [WIDTH-1:0] r1;
    always @(posedge clk) if (ce && r1_we) r1 <= r1_d;

    // r2 holds: B, Z
    reg  [WIDTH-1:0] r2_d;
    always @(*) begin
        case (r2_sel)
            1'd0: r2_d = in_B;
            1'd1: r2_d = sub0_out;
            default: r2_d = {WIDTH{1'b0}};
        endcase
    end
    reg  [WIDTH-1:0] r2;
    always @(posedge clk) if (ce && r2_we) r2 <= r2_d;

    // r3 holds: Q
    wire [WIDTH-1:0] r3_d = mul0_out;
    reg  [WIDTH-1:0] r3;
    always @(posedge clk) if (ce && r3_we) r3 <= r3_d;

    // ------------------------------------------------------------ outputs
    assign out_Q = r3;   // Q
    assign out_Z = r2;   // Z
    assign out_Y = r1;   // Y
    assign out_X = r0;   // X2

endmodule
